SELECT t_machine_sprinkler.*,
       t_sprinkler.*
FROM t_machine_sprinkler
LEFT JOIN t_sprinkler ON t_sprinkler.sprinkler_id = t_machine_sprinkler.sprinkler_id

    t_machine_sprinkler.deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(t_sprinkler.sprinkler_model,#{queryForm.sprinklerModel})


        AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') >= #{queryForm.warehouseDateStartTime}


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') <= #{queryForm.warehouseDateEndTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}


        AND INSTR(t_sprinkler.allocate_purpose,#{queryForm.allocatePurpose})


        AND INSTR(t_sprinkler.allocate_position,#{queryForm.allocatePosition})


        AND INSTR(t_sprinkler.history,#{queryForm.history})


        AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}



    ORDER BY t_sprinkler.create_time DESC


    ORDER BY




                CASE WHEN LEFT(allocate_position, 2) = 'LK' THEN 7
                ELSE FIELD(LEFT(allocate_position, 1), 'K','C','M','Y','O','B','R')
                END,
                CAST(REGEXP_REPLACE(allocate_position, '[^0-9]', '') AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}



                CASE WHEN t_sprinkler.sprinkler_serial REGEXP '^\\w{6}-\\d{2}$' THEN 0 ELSE 1 END ${sortItem.isAsc ? 'ASC' : 'DESC'},
                SUBSTRING(t_sprinkler.sprinkler_serial, 1, 6) ${sortItem.isAsc ? 'ASC' : 'DESC'},
                CAST(SUBSTRING(t_sprinkler.sprinkler_serial, 8, 2) AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}




                `${sortItem.column}` ${sortItem.isAsc ? 'ASC' : 'DESC'}

SELECT t_machine_sprinkler.*,
t_sprinkler.*
FROM t_machine_sprinkler
LEFT JOIN t_sprinkler ON t_sprinkler.sprinkler_id = t_machine_sprinkler.sprinkler_id

    t_machine_sprinkler.deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(t_sprinkler.sprinkler_model,#{queryForm.sprinklerModel})


        AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') >= #{queryForm.warehouseDateStartTime}


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') <= #{queryForm.warehouseDateEndTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}


        AND INSTR(t_sprinkler.allocate_purpose,#{queryForm.allocatePurpose})


        AND INSTR(t_sprinkler.allocate_position,#{queryForm.allocatePosition})


        AND INSTR(t_sprinkler.history,#{queryForm.history})


        AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}



    ORDER BY t_sprinkler.create_time DESC
